-- Sample data for trying the app: a generic "Demo Shop" with two branches and a small
-- catalogue.
--
-- This is NOT any real shop. A real shop gets created by `pnpm shop:init`, which asks
-- for its own name, invoice prefix and starting invoice number — so no shop inherits
-- another shop's identity or invoice sequence.
--
-- Two branches on purpose: it is the only way to notice that something is leaking
-- between branches. A one-branch sample would look fine either way.
--
-- Safe to run more than once: everything is `on conflict do nothing`.

values ('00000000-0000-4000-8000-000000000001', 'Demo Shop',
        '123 Example Road, Dhaka', '01700-000000', 'DEMO')
on conflict (id) do nothing;

   'Main branch', 'MB', '123 Example Road, Dhaka', '01700-000000', 1),
  ('00000000-0000-4000-8000-0000000000b2', '00000000-0000-4000-8000-000000000001',
   'Second branch', 'SB', '456 Other Road, Dhaka', '01700-000001', 1)
on conflict (id) do nothing;

   '00000000-0000-4000-8000-0000000000b1', 'Main store', true),
  ('00000000-0000-4000-8000-0000000000e2', '00000000-0000-4000-8000-000000000001',
   '00000000-0000-4000-8000-0000000000b2', 'Main store', true)
on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

-- Stock at the main branch. The second branch deliberately holds different numbers, so
-- a leak between branches shows up as a wrong figure rather than a plausible one.
  -- Second branch: fewer of a few things, nothing of the rest.
  ('00000000-0000-4000-8000-0000000000a1', '00000000-0000-4000-8000-0000000000e2', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-0000000000b2', 6),
  ('00000000-0000-4000-8000-0000000000a2', '00000000-0000-4000-8000-0000000000e2', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-0000000000b2', 2),
  ('00000000-0000-4000-8000-0000000000a4', '00000000-0000-4000-8000-0000000000e2', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-0000000000b2', 5),
  ('00000000-0000-4000-8000-0000000000a8', '00000000-0000-4000-8000-0000000000e2', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-0000000000b2', 1)
on conflict (product_id, location_id) do nothing;

-- Serials sit in a location, so they belong to one branch.
  -- One SSD at the second branch, so "sold at A" can be told from "sold at B".
  ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-0000000000a8', 'S64DNX0T49999', '00000000-0000-4000-8000-0000000000e2')
on conflict (shop_id, serial) do nothing;

on conflict (product_id) do nothing;
